// ============================================================
// log_parser.fl - CI/테스트 실패 로그 파서
// 지원: Rust(cargo test), Go(go test), FreeLang(fl test)
// 외부 의존성 없음
// ============================================================

// 실패 이벤트 구조체
struct FailureEvent {
  id: string,           // 고유 ID (타임스탬프 기반)
  source: string,       // "gogs_webhook" | "manual" | "ci"
  repo: string,         // 저장소 이름
  branch: string,       // 브랜치
  commit_sha: string,   // 커밋 SHA
  lang: string,         // "rust" | "go" | "freelang" | "unknown"
  error_type: string,   // "test_failure" | "compile_error" | "runtime_error"
  raw_log: string,      // 원본 로그
  timestamp: i64        // Unix timestamp
}

// 파싱된 에러 정보
struct ParsedError {
  error_type: string,    // "test_failure" | "compile_error" | "panic"
  file_path: string,     // 에러 발생 파일
  line_num: i32,         // 에러 줄 번호
  col_num: i32,          // 열 번호 (있으면)
  error_msg: string,     // 핵심 에러 메시지
  context: string,       // 주변 코드 컨텍스트
  test_name: string,     // 실패한 테스트 이름 (있으면)
  lang: string           // 언어
}

// 파서 결과
struct ParseResult {
  success: bool,
  errors: array,         // ParsedError 배열
  summary: string,       // 1줄 요약
  confidence: i32        // 파싱 신뢰도 0-100
}

// ==================== 메인 파서 ====================

fn parse_failure_log(event: FailureEvent) -> ParseResult
  intent "실패 로그를 분석해 구조화된 에러 정보 추출"
  do
    let lang = detect_language(event.raw_log, event.repo)
    let errors = []

    if lang == "rust"
      errors = parse_rust_log(event.raw_log)
    else if lang == "go"
      errors = parse_go_log(event.raw_log)
    else if lang == "freelang"
      errors = parse_freelang_log(event.raw_log)
    else
      errors = parse_generic_log(event.raw_log)
    end

    if arr_len(errors) == 0
      return ParseResult {
        success: false,
        errors: [],
        summary: "에러를 파싱하지 못했습니다",
        confidence: 0
      }
    end

    let summary = build_summary(errors, lang)
    let confidence = calc_confidence(errors, lang)

    return ParseResult {
      success: true,
      errors: errors,
      summary: summary,
      confidence: confidence
    }
end

// ==================== 언어 감지 ====================

fn detect_language(log: string, repo: string) -> string
  intent "로그 패턴 또는 저장소 이름으로 언어 감지"
  do
    // 1. 로그 패턴으로 감지
    if str_contains(log, "error[E") && str_contains(log, "--> src/")
      return "rust"
    end

    if str_contains(log, "FAIL\t") && str_contains(log, "--- FAIL:")
      return "go"
    end

    if str_contains(log, "cargo test") || str_contains(log, "Compiling ")
      return "rust"
    end

    if str_contains(log, "go test") || str_contains(log, "go build")
      return "go"
    end

    if str_contains(log, "fl test") || str_contains(log, "freelang")
      return "freelang"
    end

    // 2. 저장소 이름으로 감지
    if str_contains(repo, "rust") || str_ends_with(repo, "-rs")
      return "rust"
    end

    if str_contains(repo, "golang") || str_ends_with(repo, "-go")
      return "go"
    end

    if str_contains(repo, "freelang") || str_ends_with(repo, "-fl")
      return "freelang"
    end

    return "unknown"
end

// ==================== Rust 로그 파서 ====================

fn parse_rust_log(log: string) -> array
  intent "cargo test / rustc 에러 로그 파싱"
  do
    let errors = []
    let lines = str_split_lines(log)
    let i = 0
    let total = arr_len(lines)

    while i < total
      let line = arr_get(lines, i)

      // 컴파일 에러: "error[E0308]: ..."
      if str_starts_with(line, "error[E")
        let err = parse_rust_compile_error(lines, i)
        errors = arr_push(errors, err)
        i = i + 3  // 다음 에러로 skip
      end

      // 테스트 실패: "---- test_name stdout ----"
      if str_contains(line, "---- ") && str_contains(line, " stdout ----")
        let err = parse_rust_test_failure(lines, i)
        errors = arr_push(errors, err)
        i = i + 1
      end

      // panic: "thread 'test_name' panicked at"
      if str_contains(line, "panicked at")
        let err = parse_rust_panic(lines, i)
        errors = arr_push(errors, err)
        i = i + 1
      end

      i = i + 1
    end

    return errors
end

fn parse_rust_compile_error(lines: array, start: i32) -> ParsedError
  intent "Rust 컴파일 에러 블록 파싱"
  do
    let total = arr_len(lines)
    let error_line = arr_get(lines, start)

    // "error[E0308]: mismatched types" → 에러 메시지 추출
    let error_msg = str_after(error_line, "]: ")

    // 다음 줄에서 파일 위치: " --> src/main.rs:42:10"
    let file_path = ""
    let line_num = 0
    let col_num = 0

    if start + 1 < total
      let loc_line = arr_get(lines, start + 1)
      if str_contains(loc_line, " --> ")
        let loc = str_after(loc_line, " --> ")
        file_path = parse_rust_file(loc)
        line_num = parse_rust_line(loc)
        col_num = parse_rust_col(loc)
      end
    end

    // 컨텍스트 수집 (3줄)
    let context = collect_context(lines, start, 5)

    return ParsedError {
      error_type: "compile_error",
      file_path: file_path,
      line_num: line_num,
      col_num: col_num,
      error_msg: error_msg,
      context: context,
      test_name: "",
      lang: "rust"
    }
end

fn parse_rust_test_failure(lines: array, start: i32) -> ParsedError
  intent "Rust 테스트 실패 블록 파싱"
  do
    let header_line = arr_get(lines, start)

    // "---- tests::my_test stdout ----" → 테스트명 추출
    let test_name = str_between(header_line, "---- ", " stdout ----")

    // 실패 메시지 수집
    let context = collect_context(lines, start, 8)
    let error_msg = extract_assertion_message(lines, start)

    return ParsedError {
      error_type: "test_failure",
      file_path: "",
      line_num: 0,
      col_num: 0,
      error_msg: error_msg,
      context: context,
      test_name: test_name,
      lang: "rust"
    }
end

fn parse_rust_panic(lines: array, start: i32) -> ParsedError
  intent "Rust panic 메시지 파싱"
  do
    let panic_line = arr_get(lines, start)

    // "thread 'test_name' panicked at 'message', src/file.rs:42:10"
    let test_name = str_between(panic_line, "thread '", "' panicked")
    let panic_msg = str_between(panic_line, "panicked at '", "',")
    let location = str_after_last(panic_line, "', ")

    let file_path = parse_rust_file(location)
    let line_num = parse_rust_line(location)

    return ParsedError {
      error_type: "panic",
      file_path: file_path,
      line_num: line_num,
      col_num: 0,
      error_msg: "panic: " + panic_msg,
      context: collect_context(lines, start, 5),
      test_name: test_name,
      lang: "rust"
    }
end

// ==================== Go 로그 파서 ====================

fn parse_go_log(log: string) -> array
  intent "go test 에러 로그 파싱"
  do
    let errors = []
    let lines = str_split_lines(log)
    let i = 0
    let total = arr_len(lines)

    while i < total
      let line = arr_get(lines, i)

      // "--- FAIL: TestName (0.01s)"
      if str_starts_with(line, "--- FAIL: ")
        let err = parse_go_test_failure(lines, i)
        errors = arr_push(errors, err)
      end

      // "./file.go:42:10: error message"
      if str_contains(line, ".go:") && str_contains(line, ": ")
        let err = parse_go_compile_error(line)
        errors = arr_push(errors, err)
      end

      // "panic: message"
      if str_starts_with(line, "panic: ")
        let err = parse_go_panic(lines, i)
        errors = arr_push(errors, err)
      end

      i = i + 1
    end

    return errors
end

fn parse_go_test_failure(lines: array, start: i32) -> ParsedError
  intent "Go 테스트 실패 파싱"
  do
    let fail_line = arr_get(lines, start)

    // "--- FAIL: TestName (0.01s)" → TestName 추출
    let test_name = str_between(fail_line, "--- FAIL: ", " (")

    // 이전 줄들에서 에러 메시지 찾기
    let error_msg = ""
    let file_path = ""
    let line_num = 0

    // 최대 10줄 이전을 탐색
    let j = start - 1
    let search_limit = 0
    if start > 10
      search_limit = start - 10
    end

    while j >= search_limit
      let prev_line = arr_get(lines, j)

      // "    file_test.go:42: Error message"
      if str_contains(prev_line, "_test.go:")
        file_path = parse_go_file(prev_line)
        line_num = parse_go_line_from_test(prev_line)
        error_msg = str_after_colon3(prev_line)
      end

      j = j - 1
    end

    return ParsedError {
      error_type: "test_failure",
      file_path: file_path,
      line_num: line_num,
      col_num: 0,
      error_msg: error_msg,
      context: collect_context(lines, start, 6),
      test_name: test_name,
      lang: "go"
    }
end

fn parse_go_compile_error(line: string) -> ParsedError
  intent "Go 컴파일 에러 한 줄 파싱"
  do
    // "./main.go:15:5: undefined: someFunc"
    let file_path = str_before(line, ":")
    let rest = str_after(line, ":")
    let line_num = parse_int_from_str(str_before(rest, ":"))
    let rest2 = str_after(rest, ":")
    let col_num = parse_int_from_str(str_before(rest2, ":"))
    let error_msg = str_after(rest2, ": ")

    return ParsedError {
      error_type: "compile_error",
      file_path: file_path,
      line_num: line_num,
      col_num: col_num,
      error_msg: error_msg,
      context: "",
      test_name: "",
      lang: "go"
    }
end

fn parse_go_panic(lines: array, start: i32) -> ParsedError
  intent "Go panic 파싱"
  do
    let panic_line = arr_get(lines, start)
    let panic_msg = str_after(panic_line, "panic: ")

    // goroutine 스택 추적에서 파일 위치 찾기
    let file_path = ""
    let line_num = 0

    let total = arr_len(lines)
    let j = start + 1
    let limit = start + 10
    if limit > total
      limit = total
    end

    while j < limit
      let stack_line = arr_get(lines, j)
      // "\t/path/to/file.go:42 +0x123"
      if str_contains(stack_line, ".go:") && str_starts_with(stack_line, "\t")
        file_path = parse_go_stack_file(stack_line)
        line_num = parse_go_stack_line(stack_line)
      end
      j = j + 1
    end

    return ParsedError {
      error_type: "panic",
      file_path: file_path,
      line_num: line_num,
      col_num: 0,
      error_msg: "panic: " + panic_msg,
      context: collect_context(lines, start, 8),
      test_name: "",
      lang: "go"
    }
end

// ==================== FreeLang 로그 파서 ====================

fn parse_freelang_log(log: string) -> array
  intent "FreeLang 컴파일러/테스트 에러 로그 파싱"
  do
    let errors = []
    let lines = str_split_lines(log)
    let i = 0
    let total = arr_len(lines)

    while i < total
      let line = arr_get(lines, i)

      // "Error at src/main.fl:42: message"
      if str_starts_with(line, "Error at ")
        let err = parse_fl_error(lines, i)
        errors = arr_push(errors, err)
      end

      // "FAIL: test_name"
      if str_starts_with(line, "FAIL: ")
        let err = parse_fl_test_fail(lines, i)
        errors = arr_push(errors, err)
      end

      // "Type error: ..."
      if str_starts_with(line, "Type error: ")
        let err = parse_fl_type_error(lines, i)
        errors = arr_push(errors, err)
      end

      i = i + 1
    end

    return errors
end

fn parse_fl_error(lines: array, start: i32) -> ParsedError
  intent "FreeLang 에러 파싱"
  do
    let line = arr_get(lines, start)

    // "Error at src/main.fl:42: undefined variable 'x'"
    let location = str_between(line, "Error at ", ": ")
    let error_msg = str_after(line, location + ": ")
    let file_path = str_before(location, ":")
    let line_num = parse_int_from_str(str_after(location, ":"))

    return ParsedError {
      error_type: "compile_error",
      file_path: file_path,
      line_num: line_num,
      col_num: 0,
      error_msg: error_msg,
      context: collect_context(lines, start, 4),
      test_name: "",
      lang: "freelang"
    }
end

fn parse_fl_test_fail(lines: array, start: i32) -> ParsedError
  intent "FreeLang 테스트 실패 파싱"
  do
    let line = arr_get(lines, start)
    let test_name = str_after(line, "FAIL: ")

    // 다음 줄에서 메시지 찾기
    let error_msg = ""
    let total = arr_len(lines)
    if start + 1 < total
      error_msg = arr_get(lines, start + 1)
    end

    return ParsedError {
      error_type: "test_failure",
      file_path: "",
      line_num: 0,
      col_num: 0,
      error_msg: error_msg,
      context: collect_context(lines, start, 5),
      test_name: test_name,
      lang: "freelang"
    }
end

fn parse_fl_type_error(lines: array, start: i32) -> ParsedError
  intent "FreeLang 타입 에러 파싱"
  do
    let line = arr_get(lines, start)
    let error_msg = str_after(line, "Type error: ")

    return ParsedError {
      error_type: "type_error",
      file_path: "",
      line_num: 0,
      col_num: 0,
      error_msg: error_msg,
      context: collect_context(lines, start, 4),
      test_name: "",
      lang: "freelang"
    }
end

// ==================== 제네릭 파서 ====================

fn parse_generic_log(log: string) -> array
  intent "언어 불명확 로그 파싱 (베스트 에포트)"
  do
    let errors = []
    let lines = str_split_lines(log)
    let i = 0
    let total = arr_len(lines)

    while i < total
      let line = arr_get(lines, i)

      // "error:" 또는 "ERROR:" 패턴
      if str_contains_ci(line, "error:") || str_contains_ci(line, "fatal:")
        let err = ParsedError {
          error_type: "unknown_error",
          file_path: "",
          line_num: 0,
          col_num: 0,
          error_msg: line,
          context: collect_context(lines, i, 4),
          test_name: "",
          lang: "unknown"
        }
        errors = arr_push(errors, err)
      end

      i = i + 1
    end

    return errors
end

// ==================== 유틸리티 ====================

fn collect_context(lines: array, center: i32, radius: i32) -> string
  intent "특정 줄 주변 컨텍스트 수집"
  do
    let total = arr_len(lines)
    let start = center - radius
    if start < 0
      start = 0
    end
    let end_idx = center + radius
    if end_idx >= total
      end_idx = total - 1
    end

    let result = ""
    let i = start
    while i <= end_idx
      let marker = "  "
      if i == center
        marker = "→ "
      end
      result = result + marker + arr_get(lines, i) + "\n"
      i = i + 1
    end

    return result
end

fn build_summary(errors: array, lang: string) -> string
  intent "에러 배열에서 요약 문자열 생성"
  do
    let count = arr_len(errors)
    if count == 0
      return "에러 없음"
    end

    let first = arr_get(errors, 0)
    let summary = "[" + lang + "] " + int_to_str(count) + "개 에러: "
    summary = summary + first.error_type + " - " + str_truncate(first.error_msg, 80)

    if count > 1
      summary = summary + " (외 " + int_to_str(count - 1) + "개)"
    end

    return summary
end

fn calc_confidence(errors: array, lang: string) -> i32
  intent "파싱 신뢰도 계산 (0-100)"
  do
    if arr_len(errors) == 0
      return 0
    end

    let base = 50

    // 언어가 명확히 감지되면 +20
    if lang != "unknown"
      base = base + 20
    end

    // 파일 경로 있으면 +15
    let first = arr_get(errors, 0)
    if first.file_path != ""
      base = base + 15
    end

    // 줄 번호 있으면 +15
    if first.line_num > 0
      base = base + 15
    end

    if base > 100
      return 100
    end

    return base
end

fn extract_assertion_message(lines: array, start: i32) -> string
  intent "테스트 assertion 실패 메시지 추출"
  do
    let total = arr_len(lines)
    let i = start
    let limit = start + 8
    if limit > total
      limit = total
    end

    while i < limit
      let line = arr_get(lines, i)
      if str_contains(line, "assertion") || str_contains(line, "expected") || str_contains(line, "left ==")
        return str_trim(line)
      end
      i = i + 1
    end

    return "알 수 없는 테스트 실패"
end

// ==================== 문자열 파싱 헬퍼 ====================

fn parse_rust_file(loc: string) -> string
  // "src/main.rs:42:10" → "src/main.rs"
  do
    return str_before(loc, ":")
end

fn parse_rust_line(loc: string) -> i32
  // "src/main.rs:42:10" → 42
  do
    let after_file = str_after(loc, ":")
    return parse_int_from_str(str_before(after_file, ":"))
end

fn parse_rust_col(loc: string) -> i32
  // "src/main.rs:42:10" → 10
  do
    let after_file = str_after(loc, ":")
    let after_line = str_after(after_file, ":")
    return parse_int_from_str(after_line)
end

fn parse_go_file(line: string) -> string
  // "    file_test.go:42: Error" → "file_test.go"
  do
    let trimmed = str_trim(line)
    return str_before(trimmed, ":")
end

fn parse_go_line_from_test(line: string) -> i32
  // "    file_test.go:42: Error" → 42
  do
    let trimmed = str_trim(line)
    let after_file = str_after(trimmed, ":")
    return parse_int_from_str(str_before(after_file, ":"))
end

fn str_after_colon3(line: string) -> string
  // "    file.go:42: message" → "message"
  do
    let trimmed = str_trim(line)
    let p1 = str_after(trimmed, ":")
    let p2 = str_after(p1, ":")
    return str_trim(str_after(p2, ": "))
end

fn parse_go_stack_file(line: string) -> string
  // "\t/path/to/file.go:42 +0x123" → "/path/to/file.go"
  do
    let trimmed = str_trim(line)
    let without_tab = str_after(trimmed, "\t")
    return str_before(without_tab, ":")
end

fn parse_go_stack_line(line: string) -> i32
  // "\t/path/to/file.go:42 +0x123" → 42
  do
    let trimmed = str_trim(line)
    let after_colon = str_after(trimmed, ":")
    return parse_int_from_str(str_before(after_colon, " "))
end

fn parse_int_from_str(s: string) -> i32
  intent "문자열에서 앞부분 정수 파싱"
  do
    let num = 0
    let i = 0
    let len = str_len(s)

    while i < len
      let ch = str_char(s, i)
      let d = char_to_digit(ch)
      if d < 0
        return num  // 숫자 아닌 문자에서 중단
      end
      num = num * 10 + d
      i = i + 1
    end

    return num
end

fn char_to_digit(ch: string) -> i32
  do
    if ch == "0" return 0
    if ch == "1" return 1
    if ch == "2" return 2
    if ch == "3" return 3
    if ch == "4" return 4
    if ch == "5" return 5
    if ch == "6" return 6
    if ch == "7" return 7
    if ch == "8" return 8
    if ch == "9" return 9
    return -1
end

fn int_to_str(n: i32) -> string
  do
    if n == 0 return "0"
    let result = ""
    let num = n
    if num < 0
      num = 0 - num
    end
    while num > 0
      let d = num % 10
      if d == 0 result = "0" + result
      if d == 1 result = "1" + result
      if d == 2 result = "2" + result
      if d == 3 result = "3" + result
      if d == 4 result = "4" + result
      if d == 5 result = "5" + result
      if d == 6 result = "6" + result
      if d == 7 result = "7" + result
      if d == 8 result = "8" + result
      if d == 9 result = "9" + result
      num = num / 10
    end
    if n < 0 result = "-" + result
    return result
end

fn str_truncate(s: string, max_len: i32) -> string
  intent "문자열을 최대 길이로 자름"
  do
    let len = str_len(s)
    if len <= max_len
      return s
    end
    return str_substr(s, 0, max_len - 3) + "..."
end

fn str_contains_ci(s: string, pattern: string) -> bool
  intent "대소문자 무시 포함 검사"
  do
    return str_contains(str_lowercase(s), str_lowercase(pattern))
end

toolUseResult.content:
// ============================================================
// log_parser.fl - CI/테스트 실패 로그 파서
// 지원: Rust(cargo test), Go(go test), FreeLang(fl test)
// 외부 의존성 없음
// ============================================================

// 실패 이벤트 구조체
struct FailureEvent {
  id: string,           // 고유 ID (타임스탬프 기반)
  source: string,       // "gogs_webhook" | "manual" | "ci"
  repo: string,         // 저장소 이름
  branch: string,       // 브랜치
  commit_sha: string,   // 커밋 SHA
  lang: string,         // "rust" | "go" | "freelang" | "unknown"
  error_type: string,   // "test_failure" | "compile_error" | "runtime_error"
  raw_log: string,      // 원본 로그
  timestamp: i64        // Unix timestamp
}

// 파싱된 에러 정보
struct ParsedError {
  error_type: string,    // "test_failure" | "compile_error" | "panic"
  file_path: string,     // 에러 발생 파일
  line_num: i32,         // 에러 줄 번호
  col_num: i32,          // 열 번호 (있으면)
  error_msg: string,     // 핵심 에러 메시지
  context: string,       // 주변 코드 컨텍스트
  test_name: string,     // 실패한 테스트 이름 (있으면)
  lang: string           // 언어
}

// 파서 결과
struct ParseResult {
  success: bool,
  errors: array,         // ParsedError 배열
  summary: string,       // 1줄 요약
  confidence: i32        // 파싱 신뢰도 0-100
}

// ==================== 메인 파서 ====================

fn parse_failure_log(event: FailureEvent) -> ParseResult
  intent "실패 로그를 분석해 구조화된 에러 정보 추출"
  do
    let lang = detect_language(event.raw_log, event.repo)
    let errors = []

    if lang == "rust"
      errors = parse_rust_log(event.raw_log)
    else if lang == "go"
      errors = parse_go_log(event.raw_log)
    else if lang == "freelang"
      errors = parse_freelang_log(event.raw_log)
    else
      errors = parse_generic_log(event.raw_log)
    end

    if arr_len(errors) == 0
      return ParseResult {
        success: false,
        errors: [],
        summary: "에러를 파싱하지 못했습니다",
        confidence: 0
      }
    end

    let summary = build_summary(errors, lang)
    let confidence = calc_confidence(errors, lang)

    return ParseResult {
      success: true,
      errors: errors,
      summary: summary,
      confidence: confidence
    }
end

// ==================== 언어 감지 ====================

fn detect_language(log: string, repo: string) -> string
  intent "로그 패턴 또는 저장소 이름으로 언어 감지"
  do
    // 1. 로그 패턴으로 감지
    if str_contains(log, "error[E") && str_contains(log, "--> src/")
      return "rust"
    end

    if str_contains(log, "FAIL\t") && str_contains(log, "--- FAIL:")
      return "go"
    end

    if str_contains(log, "cargo test") || str_contains(log, "Compiling ")
      return "rust"
    end

    if str_contains(log, "go test") || str_contains(log, "go build")
      return "go"
    end

    if str_contains(log, "fl test") || str_contains(log, "freelang")
      return "freelang"
    end

    // 2. 저장소 이름으로 감지
    if str_contains(repo, "rust") || str_ends_with(repo, "-rs")
      return "rust"
    end

    if str_contains(repo, "golang") || str_ends_with(repo, "-go")
      return "go"
    end

    if str_contains(repo, "freelang") || str_ends_with(repo, "-fl")
      return "freelang"
    end

    return "unknown"
end

// ==================== Rust 로그 파서 ====================

fn parse_rust_log(log: string) -> array
  intent "cargo test / rustc 에러 로그 파싱"
  do
    let errors = []
    let lines = str_split_lines(log)
    let i = 0
    let total = arr_len(lines)

    while i < total
      let line = arr_get(lines, i)

      // 컴파일 에러: "error[E0308]: ..."
      if str_starts_with(line, "error[E")
        let err = parse_rust_compile_error(lines, i)
        errors = arr_push(errors, err)
        i = i + 3  // 다음 에러로 skip
      end

      // 테스트 실패: "---- test_name stdout ----"
      if str_contains(line, "---- ") && str_contains(line, " stdout ----")
        let err = parse_rust_test_failure(lines, i)
        errors = arr_push(errors, err)
        i = i + 1
      end

      // panic: "thread 'test_name' panicked at"
      if str_contains(line, "panicked at")
        let err = parse_rust_panic(lines, i)
        errors = arr_push(errors, err)
        i = i + 1
      end

      i = i + 1
    end

    return errors
end

fn parse_rust_compile_error(lines: array, start: i32) -> ParsedError
  intent "Rust 컴파일 에러 블록 파싱"
  do
    let total = arr_len(lines)
    let error_line = arr_get(lines, start)

    // "error[E0308]: mismatched types" → 에러 메시지 추출
    let error_msg = str_after(error_line, "]: ")

    // 다음 줄에서 파일 위치: " --> src/main.rs:42:10"
    let file_path = ""
    let line_num = 0
    let col_num = 0

    if start + 1 < total
      let loc_line = arr_get(lines, start + 1)
      if str_contains(loc_line, " --> ")
        let loc = str_after(loc_line, " --> ")
        file_path = parse_rust_file(loc)
        line_num = parse_rust_line(loc)
        col_num = parse_rust_col(loc)
      end
    end

    // 컨텍스트 수집 (3줄)
    let context = collect_context(lines, start, 5)

    return ParsedError {
      error_type: "compile_error",
      file_path: file_path,
      line_num: line_num,
      col_num: col_num,
      error_msg: error_msg,
      context: context,
      test_name: "",
      lang: "rust"
    }
end

fn parse_rust_test_failure(lines: array, start: i32) -> ParsedError
  intent "Rust 테스트 실패 블록 파싱"
  do
    let header_line = arr_get(lines, start)

    // "---- tests::my_test stdout ----" → 테스트명 추출
    let test_name = str_between(header_line, "---- ", " stdout ----")

    // 실패 메시지 수집
    let context = collect_context(lines, start, 8)
    let error_msg = extract_assertion_message(lines, start)

    return ParsedError {
      error_type: "test_failure",
      file_path: "",
      line_num: 0,
      col_num: 0,
      error_msg: error_msg,
      context: context,
      test_name: test_name,
      lang: "rust"
    }
end

fn parse_rust_panic(lines: array, start: i32) -> ParsedError
  intent "Rust panic 메시지 파싱"
  do
    let panic_line = arr_get(lines, start)

    // "thread 'test_name' panicked at 'message', src/file.rs:42:10"
    let test_name = str_between(panic_line, "thread '", "' panicked")
    let panic_msg = str_between(panic_line, "panicked at '", "',")
    let location = str_after_last(panic_line, "', ")

    let file_path = parse_rust_file(location)
    let line_num = parse_rust_line(location)

    return ParsedError {
      error_type: "panic",
      file_path: file_path,
      line_num: line_num,
      col_num: 0,
      error_msg: "panic: " + panic_msg,
      context: collect_context(lines, start, 5),
      test_name: test_name,
      lang: "rust"
    }
end

// ==================== Go 로그 파서 ====================

fn parse_go_log(log: string) -> array
  intent "go test 에러 로그 파싱"
  do
    let errors = []
    let lines = str_split_lines(log)
    let i = 0
    let total = arr_len(lines)

    while i < total
      let line = arr_get(lines, i)

      // "--- FAIL: TestName (0.01s)"
      if str_starts_with(line, "--- FAIL: ")
        let err = parse_go_test_failure(lines, i)
        errors = arr_push(errors, err)
      end

      // "./file.go:42:10: error message"
      if str_contains(line, ".go:") && str_contains(line, ": ")
        let err = parse_go_compile_error(line)
        errors = arr_push(errors, err)
      end

      // "panic: message"
      if str_starts_with(line, "panic: ")
        let err = parse_go_panic(lines, i)
        errors = arr_push(errors, err)
      end

      i = i + 1
    end

    return errors
end

fn parse_go_test_failure(lines: array, start: i32) -> ParsedError
  intent "Go 테스트 실패 파싱"
  do
    let fail_line = arr_get(lines, start)

    // "--- FAIL: TestName (0.01s)" → TestName 추출
    let test_name = str_between(fail_line, "--- FAIL: ", " (")

    // 이전 줄들에서 에러 메시지 찾기
    let error_msg = ""
    let file_path = ""
    let line_num = 0

    // 최대 10줄 이전을 탐색
    let j = start - 1
    let search_limit = 0
    if start > 10
      search_limit = start - 10
    end

    while j >= search_limit
      let prev_line = arr_get(lines, j)

      // "    file_test.go:42: Error message"
      if str_contains(prev_line, "_test.go:")
        file_path = parse_go_file(prev_line)
        line_num = parse_go_line_from_test(prev_line)
        error_msg = str_after_colon3(prev_line)
      end

      j = j - 1
    end

    return ParsedError {
      error_type: "test_failure",
      file_path: file_path,
      line_num: line_num,
      col_num: 0,
      error_msg: error_msg,
      context: collect_context(lines, start, 6),
      test_name: test_name,
      lang: "go"
    }
end

fn parse_go_compile_error(line: string) -> ParsedError
  intent "Go 컴파일 에러 한 줄 파싱"
  do
    // "./main.go:15:5: undefined: someFunc"
    let file_path = str_before(line, ":")
    let rest = str_after(line, ":")
    let line_num = parse_int_from_str(str_before(rest, ":"))
    let rest2 = str_after(rest, ":")
    let col_num = parse_int_from_str(str_before(rest2, ":"))
    let error_msg = str_after(rest2, ": ")

    return ParsedError {
      error_type: "compile_error",
      file_path: file_path,
      line_num: line_num,
      col_num: col_num,
      error_msg: error_msg,
      context: "",
      test_name: "",
      lang: "go"
    }
end

fn parse_go_panic(lines: array, start: i32) -> ParsedError
  intent "Go panic 파싱"
  do
    let panic_line = arr_get(lines, start)
    let panic_msg = str_after(panic_line, "panic: ")

    // goroutine 스택 추적에서 파일 위치 찾기
    let file_path = ""
    let line_num = 0

    let total = arr_len(lines)
    let j = start + 1
    let limit = start + 10
    if limit > total
      limit = total
    end

    while j < limit
      let stack_line = arr_get(lines, j)
      // "\t/path/to/file.go:42 +0x123"
      if str_contains(stack_line, ".go:") && str_starts_with(stack_line, "\t")
        file_path = parse_go_stack_file(stack_line)
        line_num = parse_go_stack_line(stack_line)
      end
      j = j + 1
    end

    return ParsedError {
      error_type: "panic",
      file_path: file_path,
      line_num: line_num,
      col_num: 0,
      error_msg: "panic: " + panic_msg,
      context: collect_context(lines, start, 8),
      test_name: "",
      lang: "go"
    }
end

// ==================== FreeLang 로그 파서 ====================

fn parse_freelang_log(log: string) -> array
  intent "FreeLang 컴파일러/테스트 에러 로그 파싱"
  do
    let errors = []
    let lines = str_split_lines(log)
    let i = 0
    let total = arr_len(lines)

    while i < total
      let line = arr_get(lines, i)

      // "Error at src/main.fl:42: message"
      if str_starts_with(line, "Error at ")
        let err = parse_fl_error(lines, i)
        errors = arr_push(errors, err)
      end

      // "FAIL: test_name"
      if str_starts_with(line, "FAIL: ")
        let err = parse_fl_test_fail(lines, i)
        errors = arr_push(errors, err)
      end

      // "Type error: ..."
      if str_starts_with(line, "Type error: ")
        let err = parse_fl_type_error(lines, i)
        errors = arr_push(errors, err)
      end

      i = i + 1
    end

    return errors
end

fn parse_fl_error(lines: array, start: i32) -> ParsedError
  intent "FreeLang 에러 파싱"
  do
    let line = arr_get(lines, start)

    // "Error at src/main.fl:42: undefined variable 'x'"
    let location = str_between(line, "Error at ", ": ")
    let error_msg = str_after(line, location + ": ")
    let file_path = str_before(location, ":")
    let line_num = parse_int_from_str(str_after(location, ":"))

    return ParsedError {
      error_type: "compile_error",
      file_path: file_path,
      line_num: line_num,
      col_num: 0,
      error_msg: error_msg,
      context: collect_context(lines, start, 4),
      test_name: "",
      lang: "freelang"
    }
end

fn parse_fl_test_fail(lines: array, start: i32) -> ParsedError
  intent "FreeLang 테스트 실패 파싱"
  do
    let line = arr_get(lines, start)
    let test_name = str_after(line, "FAIL: ")

    // 다음 줄에서 메시지 찾기
    let error_msg = ""
    let total = arr_len(lines)
    if start + 1 < total
      error_msg = arr_get(lines, start + 1)
    end

    return ParsedError {
      error_type: "test_failure",
      file_path: "",
      line_num: 0,
      col_num: 0,
      error_msg: error_msg,
      context: collect_context(lines, start, 5),
      test_name: test_name,
      lang: "freelang"
    }
end

fn parse_fl_type_error(lines: array, start: i32) -> ParsedError
  intent "FreeLang 타입 에러 파싱"
  do
    let line = arr_get(lines, start)
    let error_msg = str_after(line, "Type error: ")

    return ParsedError {
      error_type: "type_error",
      file_path: "",
      line_num: 0,
      col_num: 0,
      error_msg: error_msg,
      context: collect_context(lines, start, 4),
      test_name: "",
      lang: "freelang"
    }
end

// ==================== 제네릭 파서 ====================

fn parse_generic_log(log: string) -> array
  intent "언어 불명확 로그 파싱 (베스트 에포트)"
  do
    let errors = []
    let lines = str_split_lines(log)
    let i = 0
    let total = arr_len(lines)

    while i < total
      let line = arr_get(lines, i)

      // "error:" 또는 "ERROR:" 패턴
      if str_contains_ci(line, "error:") || str_contains_ci(line, "fatal:")
        let err = ParsedError {
          error_type: "unknown_error",
          file_path: "",
          line_num: 0,
          col_num: 0,
          error_msg: line,
          context: collect_context(lines, i, 4),
          test_name: "",
          lang: "unknown"
        }
        errors = arr_push(errors, err)
      end

      i = i + 1
    end

    return errors
end

// ==================== 유틸리티 ====================

fn collect_context(lines: array, center: i32, radius: i32) -> string
  intent "특정 줄 주변 컨텍스트 수집"
  do
    let total = arr_len(lines)
    let start = center - radius
    if start < 0
      start = 0
    end
    let end_idx = center + radius
    if end_idx >= total
      end_idx = total - 1
    end

    let result = ""
    let i = start
    while i <= end_idx
      let marker = "  "
      if i == center
        marker = "→ "
      end
      result = result + marker + arr_get(lines, i) + "\n"
      i = i + 1
    end

    return result
end

fn build_summary(errors: array, lang: string) -> string
  intent "에러 배열에서 요약 문자열 생성"
  do
    let count = arr_len(errors)
    if count == 0
      return "에러 없음"
    end

    let first = arr_get(errors, 0)
    let summary = "[" + lang + "] " + int_to_str(count) + "개 에러: "
    summary = summary + first.error_type + " - " + str_truncate(first.error_msg, 80)

    if count > 1
      summary = summary + " (외 " + int_to_str(count - 1) + "개)"
    end

    return summary
end

fn calc_confidence(errors: array, lang: string) -> i32
  intent "파싱 신뢰도 계산 (0-100)"
  do
    if arr_len(errors) == 0
      return 0
    end

    let base = 50

    // 언어가 명확히 감지되면 +20
    if lang != "unknown"
      base = base + 20
    end

    // 파일 경로 있으면 +15
    let first = arr_get(errors, 0)
    if first.file_path != ""
      base = base + 15
    end

    // 줄 번호 있으면 +15
    if first.line_num > 0
      base = base + 15
    end

    if base > 100
      return 100
    end

    return base
end

fn extract_assertion_message(lines: array, start: i32) -> string
  intent "테스트 assertion 실패 메시지 추출"
  do
    let total = arr_len(lines)
    let i = start
    let limit = start + 8
    if limit > total
      limit = total
    end

    while i < limit
      let line = arr_get(lines, i)
      if str_contains(line, "assertion") || str_contains(line, "expected") || str_contains(line, "left ==")
        return str_trim(line)
      end
      i = i + 1
    end

    return "알 수 없는 테스트 실패"
end

// ==================== 문자열 파싱 헬퍼 ====================

fn parse_rust_file(loc: string) -> string
  // "src/main.rs:42:10" → "src/main.rs"
  do
    return str_before(loc, ":")
end

fn parse_rust_line(loc: string) -> i32
  // "src/main.rs:42:10" → 42
  do
    let after_file = str_after(loc, ":")
    return parse_int_from_str(str_before(after_file, ":"))
end

fn parse_rust_col(loc: string) -> i32
  // "src/main.rs:42:10" → 10
  do
    let after_file = str_after(loc, ":")
    let after_line = str_after(after_file, ":")
    return parse_int_from_str(after_line)
end

fn parse_go_file(line: string) -> string
  // "    file_test.go:42: Error" → "file_test.go"
  do
    let trimmed = str_trim(line)
    return str_before(trimmed, ":")
end

fn parse_go_line_from_test(line: string) -> i32
  // "    file_test.go:42: Error" → 42
  do
    let trimmed = str_trim(line)
    let after_file = str_after(trimmed, ":")
    return parse_int_from_str(str_before(after_file, ":"))
end

fn str_after_colon3(line: string) -> string
  // "    file.go:42: message" → "message"
  do
    let trimmed = str_trim(line)
    let p1 = str_after(trimmed, ":")
    let p2 = str_after(p1, ":")
    return str_trim(str_after(p2, ": "))
end

fn parse_go_stack_file(line: string) -> string
  // "\t/path/to/file.go:42 +0x123" → "/path/to/file.go"
  do
    let trimmed = str_trim(line)
    let without_tab = str_after(trimmed, "\t")
    return str_before(without_tab, ":")
end

fn parse_go_stack_line(line: string) -> i32
  // "\t/path/to/file.go:42 +0x123" → 42
  do
    let trimmed = str_trim(line)
    let after_colon = str_after(trimmed, ":")
    return parse_int_from_str(str_before(after_colon, " "))
end

fn parse_int_from_str(s: string) -> i32
  intent "문자열에서 앞부분 정수 파싱"
  do
    let num = 0
    let i = 0
    let len = str_len(s)

    while i < len
      let ch = str_char(s, i)
      let d = char_to_digit(ch)
      if d < 0
        return num  // 숫자 아닌 문자에서 중단
      end
      num = num * 10 + d
      i = i + 1
    end

    return num
end

fn char_to_digit(ch: string) -> i32
  do
    if ch == "0" return 0
    if ch == "1" return 1
    if ch == "2" return 2
    if ch == "3" return 3
    if ch == "4" return 4
    if ch == "5" return 5
    if ch == "6" return 6
    if ch == "7" return 7
    if ch == "8" return 8
    if ch == "9" return 9
    return -1
end

fn int_to_str(n: i32) -> string
  do
    if n == 0 return "0"
    let result = ""
    let num = n
    if num < 0
      num = 0 - num
    end
    while num > 0
      let d = num % 10
      if d == 0 result = "0" + result
      if d == 1 result = "1" + result
      if d == 2 result = "2" + result
      if d == 3 result = "3" + result
      if d == 4 result = "4" + result
      if d == 5 result = "5" + result
      if d == 6 result = "6" + result
      if d == 7 result = "7" + result
      if d == 8 result = "8" + result
      if d == 9 result = "9" + result
      num = num / 10
    end
    if n < 0 result = "-" + result
    return result
end

fn str_truncate(s: string, max_len: i32) -> string
  intent "문자열을 최대 길이로 자름"
  do
    let len = str_len(s)
    if len <= max_len
      return s
    end
    return str_substr(s, 0, max_len - 3) + "..."
end

fn str_contains_ci(s: string, pattern: string) -> bool
  intent "대소문자 무시 포함 검사"
  do
    return str_contains(str_lowercase(s), str_lowercase(pattern))
end

