// ============================================================
// webhook.fl - HTTP Webhook 서버
// raw TCP 소켓 - 외부 라이브러리 없음
// POST /webhook/push, /webhook/ci, /webhook/manual
// ============================================================

struct WebhookServer {
  host: string,
  port: i32,
  cfg: AgentConfig
}

struct HttpRequest {
  method: string,
  path: string,
  headers: array,     // "Key: Value" 문자열 배열
  body: string,
  client_ip: string
}

struct HttpResponse {
  status: i32,
  status_text: string,
  body: string
}

// ==================== 서버 시작 ====================

fn webhook_server_start(cfg: AgentConfig) -> Result<void, string>
  intent "Webhook HTTP 서버 메인 루프"
  do
    print("🚀 Self-Healing Agent Webhook Server")
    print("   주소: " + cfg.webhook_host + ":" + int_to_str(cfg.webhook_port))
    print("   엔드포인트:")
    print("     POST /webhook/push    - GOGS push 이벤트")
    print("     POST /webhook/ci      - CI 실패 이벤트")
    print("     POST /webhook/manual  - 수동 트리거")
    print("     GET  /health          - 헬스체크")
    print("     GET  /status          - 현재 상태")

    // 소켓 생성
    let server_fd_result = socket_create()
    match server_fd_result
      Err(e) => return Err("소켓 생성 실패: " + e)
      Ok(server_fd) => {
        // SO_REUSEADDR
        socket_set_reuse_addr(server_fd)

        // 바인드
        match socket_bind(server_fd, cfg.webhook_host, cfg.webhook_port)
          Err(e) => return Err("바인드 실패: " + e)
          Ok(_) => {}
        end

        // 리슨
        match socket_listen(server_fd, 128)
          Err(e) => return Err("리슨 실패: " + e)
          Ok(_) => {}
        end

        print("✅ 서버 준비 완료")

        // Accept 루프
        return accept_loop(server_fd, cfg)
      }
    end
end

fn accept_loop(server_fd: i32, cfg: AgentConfig) -> Result<void, string>
  intent "클라이언트 연결 수락 루프"
  do
    while true
      match socket_accept(server_fd)
        Ok(client_fd) => {
          handle_connection(client_fd, cfg)
        }
        Err(e) => {
          print("⚠️  accept 에러: " + e)
          // 계속 실행
        }
      end
    end

    return Ok(void)
end

// ==================== 요청 처리 ====================

fn handle_connection(client_fd: i32, cfg: AgentConfig) -> void
  intent "단일 HTTP 요청 처리"
  do
    // 요청 읽기
    let raw_result = socket_read(client_fd, 65536)
    match raw_result
      Err(_) => {
        socket_close(client_fd)
        return
      }
      Ok(raw_bytes) => {
        let raw_str = bytes_to_string(raw_bytes)
        let req = parse_http_request(raw_str)
        let resp = route_request(req, cfg)
        let resp_bytes = format_http_response(resp)
        socket_write(client_fd, resp_bytes)
        socket_close(client_fd)
      }
    end
end

fn route_request(req: HttpRequest, cfg: AgentConfig) -> HttpResponse
  intent "URL 경로별 라우팅"
  do
    // 로깅
    print("[" + req.method + "] " + req.path + " from " + req.client_ip)

    // 헬스체크
    if req.method == "GET" && req.path == "/health"
      return HttpResponse {
        status: 200,
        status_text: "OK",
        body: "{\"status\":\"ok\",\"agent\":\"self-healing\"}"
      }
    end

    // 상태
    if req.method == "GET" && req.path == "/status"
      return handle_status(cfg)
    end

    // Webhook POST 엔드포인트들
    if req.method == "POST"
      if req.path == "/webhook/push"
        return handle_push_webhook(req, cfg)
      end

      if req.path == "/webhook/ci"
        return handle_ci_webhook(req, cfg)
      end

      if req.path == "/webhook/manual"
        return handle_manual_trigger(req, cfg)
      end
    end

    // 404
    return HttpResponse {
      status: 404,
      status_text: "Not Found",
      body: "{\"error\":\"경로를 찾을 수 없습니다: " + req.path + "\"}"
    }
end

// ==================== 핸들러들 ====================

fn handle_push_webhook(req: HttpRequest, cfg: AgentConfig) -> HttpResponse
  intent "GOGS push 이벤트 처리"
  do
    // GOGS 시크릿 검증 (선택적)
    let secret = get_header(req.headers, "X-Gogs-Signature")

    // 페이로드 파싱
    let event_result = parse_webhook_push(req.body)
    match event_result
      Err(e) => {
        return HttpResponse {
          status: 400,
          status_text: "Bad Request",
          body: "{\"error\":\"페이로드 파싱 실패: " + json_escape(e) + "\"}"
        }
      }
      Ok(event) => {
        // CI 실패 여부 확인 (push만으로는 판단 불가 - CI 결과 기다림)
        print("[Push Webhook] " + event.repo + "#" + str_substr(event.commit_sha, 0, 8))

        return HttpResponse {
          status: 200,
          status_text: "OK",
          body: "{\"status\":\"received\",\"repo\":\"" + event.repo + "\"," +
                "\"sha\":\"" + str_substr(event.commit_sha, 0, 8) + "\"}"
        }
      }
    end
end

fn handle_ci_webhook(req: HttpRequest, cfg: AgentConfig) -> HttpResponse
  intent "CI 실패 이벤트 처리 → 자가치유 트리거"
  do
    let event_result = parse_webhook_ci_failure(req.body)
    match event_result
      Err(e) => {
        return HttpResponse {
          status: 400,
          status_text: "Bad Request",
          body: "{\"error\":\"" + json_escape(e) + "\"}"
        }
      }
      Ok(event) => {
        print("[CI Webhook] 자가치유 시작: " + event.repo + "/" + event.branch)

        // 비동기로 자가치유 실행
        let result = heal(event, cfg)

        let resp_body = "{\"status\":\"" + (if result.success "success" else "failed") + "\"," +
                        "\"session\":\"" + result.session_id + "\"," +
                        "\"pr_url\":\"" + result.pr_url + "\"," +
                        "\"attempts\":" + int_to_str(result.attempts) + "," +
                        "\"summary\":\"" + json_escape(result.summary) + "\"}"

        let status_code = 200
        if !result.success
          status_code = 422
        end

        return HttpResponse {
          status: status_code,
          status_text: "OK",
          body: resp_body
        }
      }
    end
end

fn handle_manual_trigger(req: HttpRequest, cfg: AgentConfig) -> HttpResponse
  intent "수동 자가치유 트리거 (테스트/디버그용)"
  do
    // body: {"repo": "...", "branch": "...", "sha": "...", "log": "..."}
    let repo = json_extract_string(req.body, "repo")
    let branch = json_extract_string(req.body, "branch")
    let sha = json_extract_string(req.body, "sha")
    let log = json_extract_string(req.body, "log")
    let lang = json_extract_string(req.body, "lang")

    if repo == ""
      return HttpResponse {
        status: 400,
        status_text: "Bad Request",
        body: "{\"error\":\"repo 필드가 필요합니다\"}"
      }
    end

    let event = FailureEvent {
      id: "manual_" + int_to_str(now_unix()),
      source: "manual",
      repo: repo,
      branch: if branch == "" "main" else branch,
      commit_sha: if sha == "" "HEAD" else sha,
      lang: lang,
      error_type: "manual",
      raw_log: log,
      timestamp: now_unix()
    }

    print("[Manual] 자가치유 트리거: " + repo)
    let result = heal(event, cfg)

    return HttpResponse {
      status: if result.success 200 else 422,
      status_text: "OK",
      body: "{\"success\":" + (if result.success "true" else "false") + "," +
            "\"pr_url\":\"" + result.pr_url + "\"," +
            "\"summary\":\"" + json_escape(result.summary) + "\"}"
    }
end

fn handle_status(cfg: AgentConfig) -> HttpResponse
  intent "에이전트 상태 조회"
  do
    // 메모리 파일에서 최근 기록 읽기
    let memory_content = ""
    match file_read(cfg.memory_path)
      Ok(content) => memory_content = content
      Err(_) => memory_content = ""
    end

    let lines = str_split_lines(memory_content)
    let total = arr_len(lines)
    let success_count = 0
    let fail_count = 0

    let i = 0
    while i < total
      let line = arr_get(lines, i)
      if str_contains(line, "\"status\":\"success\"")
        success_count = success_count + 1
      else if str_contains(line, "\"status\":\"failed\"")
        fail_count = fail_count + 1
      end
      i = i + 1
    end

    let total_heals = success_count + fail_count
    let success_rate = 0
    if total_heals > 0
      success_rate = (success_count * 100) / total_heals
    end

    return HttpResponse {
      status: 200,
      status_text: "OK",
      body: "{\"agent\":\"self-healing\"," +
            "\"total_heals\":" + int_to_str(total_heals) + "," +
            "\"success\":" + int_to_str(success_count) + "," +
            "\"failed\":" + int_to_str(fail_count) + "," +
            "\"success_rate\":" + int_to_str(success_rate) + "}"
    }
end

// ==================== HTTP 파서 ====================

fn parse_http_request(raw: string) -> HttpRequest
  intent "HTTP 요청 문자열 파싱"
  do
    let lines = str_split_lines(raw)
    let total = arr_len(lines)

    if total == 0
      return HttpRequest { method: "", path: "", headers: [], body: "", client_ip: "" }
    end

    // 요청 라인: "POST /webhook/ci HTTP/1.1"
    let request_line = arr_get(lines, 0)
    let method = str_before(request_line, " ")
    let rest = str_after(request_line, " ")
    let path = str_before(rest, " ")

    // 헤더 파싱
    let headers = []
    let body_start = 0
    let i = 1

    while i < total
      let line = arr_get(lines, i)
      if str_len(str_trim(line)) == 0
        body_start = i + 1
        break
      end
      headers = arr_push(headers, line)
      i = i + 1
    end

    // 바디 수집
    let body = ""
    let j = body_start
    while j < total
      if j > body_start
        body = body + "\n"
      end
      body = body + arr_get(lines, j)
      j = j + 1
    end

    return HttpRequest {
      method: method,
      path: path,
      headers: headers,
      body: body,
      client_ip: ""
    }
end

fn format_http_response(resp: HttpResponse) -> array
  intent "HttpResponse를 바이트 배열로 직렬화"
  do
    let body_len = str_len(resp.body)

    let header = "HTTP/1.1 " + int_to_str(resp.status) + " " + resp.status_text + "\r\n" +
                 "Content-Type: application/json\r\n" +
                 "Content-Length: " + int_to_str(body_len) + "\r\n" +
                 "Connection: close\r\n" +
                 "\r\n"

    return string_to_bytes(header + resp.body)
end

fn get_header(headers: array, key: string) -> string
  intent "헤더 배열에서 특정 키 값 찾기"
  do
    let total = arr_len(headers)
    let i = 0
    let key_lower = str_lowercase(key) + ":"

    while i < total
      let header = arr_get(headers, i)
      if str_starts_with(str_lowercase(header), key_lower)
        return str_trim(str_after(header, ":"))
      end
      i = i + 1
    end

    return ""
end

// ==================== 유틸리티 ====================

fn json_extract_string(json: string, key: string) -> string
  do
    let search = "\"" + key + "\":\""
    if str_contains(json, search)
      let after = str_after(json, search)
      let result = ""
      let i = 0
      let len = str_len(after)
      while i < len
        let ch = str_char(after, i)
        if ch == "\\"
          i = i + 1
          if i < len
            result = result + str_char(after, i)
          end
        else if ch == "\""
          return result
        else
          result = result + ch
        end
        i = i + 1
      end
    end
    return ""
end

fn json_escape(s: string) -> string
  do
    let result = ""
    let i = 0
    let len = str_len(s)
    while i < len
      let ch = str_char(s, i)
      if ch == "\"" result = result + "\\\""
      else if ch == "\\" result = result + "\\\\"
      else if ch == "\n" result = result + "\\n"
      else result = result + ch
      i = i + 1
    end
    return result
end

fn int_to_str(n: i32) -> string
  do
    if n == 0 return "0"
    let result = ""
    let num = n
    let neg = false
    if num < 0
      neg = true
      num = 0 - num
    end
    while num > 0
      let d = num % 10
      if d == 0 result = "0" + result
      if d == 1 result = "1" + result
      if d == 2 result = "2" + result
      if d == 3 result = "3" + result
      if d == 4 result = "4" + result
      if d == 5 result = "5" + result
      if d == 6 result = "6" + result
      if d == 7 result = "7" + result
      if d == 8 result = "8" + result
      if d == 9 result = "9" + result
      num = num / 10
    end
    if neg result = "-" + result
    return result
end

